// inputs. There are no combinatorial next-state functions.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    parameter [1:0] ST_WALK_LEFT = 2'd0;
    parameter [1:0] ST_WALK_RIGHT = 2'd1;
    parameter [1:0] ST_FALL = 2'd2;
    parameter [1:0] ST_DIG_LEFT = 2'd3;
    parameter [1:0] ST_DIG_RIGHT = 2'd4;
    reg [1:0] state, nextstate;
    reg [23:0] fallcounter;
    always @(posedge clk) begin
        if (areset) begin
            state <= ST_WALK_LEFT;
            fallcounter <= 24'd0;
        end else begin
            state <= nextstate;
            if (fallcounter != 24'd0) fallcounter <= fallcounter - 24'd1;
        end
    end
    always @(*) begin
