                if (bump_right) nextstate = ST_WALK_RIGHT;
                else if (bump_left) nextstate = ST_FALL;
                else if (ground == 1'b0) nextstate = ST_FALL;
                else if (dig) nextstate = ST_DIG_LEFT;
