            ST_WALK_RIGHT: begin
                walk_right = 1'b1;
                if (bump_left) nextstate = ST_WALK_LEFT;
                else if (bump_right) nextstate = ST_FALL;
                else if (ground == 1'b0) nextstate = ST_FALL;
                else if (dig) nextstate = ST_DIG_RIGHT;
