// Moore FSM, one register per output, explicitly named named registers per
// state, one multiplexer per output, a single register for the state, and a
// counter to limit splatting after too long falling.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    reg [1:0] state, next_state;
    reg [23:0] fall_counter;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            fall_counter <= 24'd0;
        end else begin
            state <= next_state;
            fall_counter <= fall_counter + 24'd1;
        end
    end
    always @(*) begin
        case (state)
            2'b00: begin // walking left
                walk_left = 1;
                walk_right = 0;
                aaah = 0;
                digging = 0;
                if (bump_left) next_state = 2'b01;
                else if (bump_right) next_state = 2'b10;
                else if (ground) next_state = 2'b00;
                else if (dig) next_state = 2'b11;
                else next_state = 2'b00;
