                walk_left = 0;
                walk_right = 1;
                aaah = 0;
                digging = 0;
                if (bump_left) next_state = 2'b00;
                else if (bump_right) next_state = 2'b11;
                else if (ground) next_state = 2'b01;
                else if (dig) next_state = 2'b11;
