    reg [1:0] state, next_state;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            fall_counter <= 6'd0;
        end else begin
            state <= next_state;
            fall_counter <= (state == 2'b00 && ground == 1'b0) ? fall_counter + 6'd1 : 6'd0;
        end
    end
    always @(*) begin
        case (state)
            2'b00: begin // walking right
                walk_right <= 1'b1;
                walk_left <= 1'b0;
                aaah <= 1'b0;
