// Moore finite state machine, one-hot output for each state. Same function
// as the previous one, but explicitly named states and one-hot outputs.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    reg [1:0] state, nextstate;
    reg [23:0] fall_counter;
    always @(*) begin
        case (state)
            2'b00: begin // walking left
                nextstate = bump_left ? 2'b01 : (dig ? 2'b10 : (ground ? 2'b00 : 2'b11));
            end
            2'b01: begin // walking right
                nextstate = bump_right ? 2'b00 : (dig ? 2'b10 : (ground ? 2'b01 : 2'b11));
            end
            2'b10: begin // digging
                nextstate = ground ? (bump_left ? 2'b01 : 2'b00) : 2'b11;
            end
            2'b11: begin // falling
                nextstate = 2'b11;
            end
        endcase
    end
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            fall_counter <= 24'd0;
